window.officeBundle = {"date":"2026-11-16","services":{"morning_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"I was glad when they said unto me, \u201cWe will go into the house of the Lord."},{"line_type":"citation","content":"PSALM 122:1"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Venite"},{"line_type":"subheading","content":"O Come"},{"line_type":"rubric","content":"Officiant and People, all standing"},{"line_type":"leader","content":"The earth is the Lord\u2019s for he made it:"},{"line_type":"congregation","content":"O come, let us adore him."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"O come, let us sing unto the Lord; *"},{"line_type":"congregation","content":"let us heartily rejoice in the strength of our salvation."},{"line_type":"congregation","content":"Let us come before his presence with thanksgiving *"},{"line_type":"congregation","content":"and show ourselves glad in him with psalms."},{"line_type":"congregation","content":"For the Lord is a great God *"},{"line_type":"congregation","content":"and a great King above all gods."},{"line_type":"congregation","content":"In his hand are all the depths of the earth, *"},{"line_type":"congregation","content":"and the heights of the hills are his also."},{"line_type":"congregation","content":"The sea is his, for he made it, *"},{"line_type":"congregation","content":"and his hands prepared the dry land."},{"line_type":"congregation","content":"O come, let us worship and fall down, *"},{"line_type":"congregation","content":"and kneel before the Lord our Maker."},{"line_type":"congregation","content":"For he is our God, *"},{"line_type":"congregation","content":"and we are the people of his pasture,"},{"line_type":"congregation","content":"and the sheep of his hand."},{"line_type":"rubric","content":"The following verses may be omitted."},{"line_type":"congregation","content":"Today, if you will hear his voice, harden not your hearts *"},{"line_type":"congregation","content":"as in the provocation, and as in the day of temptation in the wilderness,"},{"line_type":"congregation","content":"When your fathers tested me, *"},{"line_type":"congregation","content":"and put me to the proof, though they had seen my works."},{"line_type":"congregation","content":"Forty years long was I grieved with this generation and said, *"},{"line_type":"congregation","content":"\u201cIt is a people that err in their hearts, for they have not known my ways,\u201d"},{"line_type":"congregation","content":"Of whom I swore in my wrath *"},{"line_type":"congregation","content":"that they should not enter into my rest."},{"line_type":"citation","content":"Psalm 95:1-7, 8-11"},{"line_type":"leader","content":"The earth is the Lord\u2019s for he made it:"},{"line_type":"congregation","content":"O come, let us adore him."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 42"},{"line_type":"subheading","content":"Quemadmodum"},{"line_type":"leader","content":"As the deer desires the water brooks, *","preface":1},{"line_type":"leader","content":"so longs my soul for you, O God."},{"line_type":"congregation","content":"My soul is athirst for God, even for the living God; *","preface":2},{"line_type":"congregation","content":"when shall I come to appear before the presence of God?"},{"line_type":"leader","content":"My tears have been my food day and night, *","preface":3},{"line_type":"leader","content":"while all day long they say to me, \u201cWhere now is your God?\u201d"},{"line_type":"congregation","content":"When I think upon these things, I pour out my heart, *","preface":4},{"line_type":"congregation","content":"when I remember how I went with the multitude, and brought them into the house of God,"},{"line_type":"leader","content":"With the voice of praise and thanksgiving *","preface":5},{"line_type":"leader","content":"among those who keep holy day."},{"line_type":"congregation","content":"Why are you so full of heaviness, O my soul, *","preface":6},{"line_type":"congregation","content":"and why are you so disquieted within me?"},{"line_type":"leader","content":"O put your trust in God, *","preface":7},{"line_type":"leader","content":"for I will yet give him thanks, who is the help of my countenance, and my God."},{"line_type":"congregation","content":"My soul is heavy within me; *","preface":8},{"line_type":"congregation","content":"therefore I will remember you from the land of Jordan, and from Mizar among the hills of Hermon."},{"line_type":"leader","content":"One deep calls to another in the noise of your waterfalls; *","preface":9},{"line_type":"leader","content":"all your waves and storms have gone over me."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 will grant his loving-kindness in the daytime; *","preface":10},{"line_type":"congregation","content":"and in the night season will I sing of him, and make my prayer to the God of my life."},{"line_type":"leader","content":"I will say to God my rock, \u201cWhy have you forgotten me? *","preface":11},{"line_type":"leader","content":"Why am I full of heaviness, while the enemy oppresses me?\u201d"},{"line_type":"congregation","content":"My bones are broken asunder, *","preface":12},{"line_type":"congregation","content":"while my enemies mock me to my face,"},{"line_type":"leader","content":"While all day long they say to me, *","preface":13},{"line_type":"leader","content":"\u201cWhere now is your God?\u201d"},{"line_type":"congregation","content":"Why are you so full of heaviness, O my soul, *","preface":14},{"line_type":"congregation","content":"and why are you so disquieted within me?"},{"line_type":"leader","content":"O put your trust in God, *","preface":15},{"line_type":"leader","content":"for I will yet give him thanks, who is the help of my countenance, and my God."},{"line_type":"heading","content":"Psalm 43"},{"line_type":"subheading","content":"Judica me, Deus"},{"line_type":"leader","content":"Give judgment for me, O God, and defend my cause against the ungodly people; *","preface":1},{"line_type":"leader","content":"O deliver me from the deceitful and the wicked."},{"line_type":"congregation","content":"For you are the God of my strength; why have you put me far from you? *","preface":2},{"line_type":"congregation","content":"And why do I go about with heaviness, while the enemy oppresses me?"},{"line_type":"leader","content":"O send out your light and your truth, that they may lead me, *","preface":3},{"line_type":"leader","content":"and bring me to your holy hill, and to your dwelling;"},{"line_type":"congregation","content":"That I may go to the altar of God, even to the God of my joy and gladness; *","preface":4},{"line_type":"congregation","content":"and on the harp will I give thanks to you, O God, my God."},{"line_type":"leader","content":"Why are you so full of heaviness, O my soul? *","preface":5},{"line_type":"leader","content":"and why are you so disquieted within me?"},{"line_type":"congregation","content":"O put your trust in God, *","preface":6},{"line_type":"congregation","content":"for I will yet give him thanks, who is the help of my countenance, and my God."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Judith 10"},{"line_type":"reader","content":"A reading from the Book of Judith, beginning with the tenth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_b62cc168-ef20-5495-9538-7be501542d3b'></span><p><span class=\"cc vnumVis\">10</span>Now after that she had ceased to cry unto the God of Israel, and bad made an end of all these words. <sup>2\u00a0</sup>She rose where she had fallen down, and called her maid, and went down into the house in the which she abode in the sabbath days, and in her feast days, <sup>3\u00a0</sup>And pulled off the sackcloth which she had on, and put off the garments of her widowhood, and washed her body all over with water, and anointed herself with precious ointment, and braided the hair of her head, and put on a tire upon it, and put on her garments of gladness, wherewith she was clad during the life of Manasses her husband. <sup>4\u00a0</sup>And she took sandals upon her feet, and put about her her bracelets, and her chains, and her rings, and her earrings, and all her ornaments, and decked herself bravely, to allure the eyes of all men that should see her. <sup>5\u00a0</sup>Then she gave her maid a bottle of wine, and a cruse of oil, and filled a bag with parched corn, and lumps of figs, and with fine bread; so she folded all these things together, and laid them upon her. <sup>6\u00a0</sup>Thus they went forth to the gate of the city of Bethulia, and found standing there Ozias and the ancients of the city, Chabris and Charmis. <sup>7\u00a0</sup>And when they saw her, that her countenance was altered, and her apparel was changed, they wondered at her beauty very greatly, and said unto her. <sup>8\u00a0</sup>The God, the God of our fathers give thee favour, and accomplish thine enterprizes to the glory of the children of Israel, and to the exaltation of Jerusalem. Then they worshipped God. <sup>9\u00a0</sup>And she said unto them, Command the gates of the city to be opened unto me, that I may go forth to accomplish the things whereof ye have spoken with me. So they commanded the young men to open unto her, as she had spoken. <sup>10\u00a0</sup>And when they had done so, Judith went out, she, and her maid with her; and the men of the city looked after her, until she was gone down the mountain, and till she had passed the valley, and could see her no more. <sup>11\u00a0</sup>Thus they went straight forth in the valley: and the first watch of the Assyrians met her, <sup>12\u00a0</sup>And took her, and asked her, Of what people art thou? and whence comest thou? and whither goest thou? And she said, I am a woman of the Hebrews, and am fled from them: for they shall be given you to be consumed: <sup>13\u00a0</sup>And I am coming before Holofernes the chief captain of your army, to declare words of truth; and I will shew him a way, whereby he shall go, and win all the hill country, without losing the body or life of any one of his men. <sup>14\u00a0</sup>Now when the men heard her words, and beheld her countenance, they wondered greatly at her beauty, and said unto her, <sup>15\u00a0</sup>Thou hast saved thy life, in that thou hast hasted to come down to the presence of our lord: now therefore come to his tent, and some of us shall conduct thee, until they have delivered thee to his hands. <sup>16\u00a0</sup>And when thou standest before him, be not afraid in thine heart, but shew unto him according to thy word; and he will entreat thee well. <sup>17\u00a0</sup>Then they chose out of them an hundred men to accompany her and her maid; and they brought her to the tent of Holofernes. <sup>18\u00a0</sup>Then was there a concourse throughout all the camp: for her coming was noised among the tents, and they came about her, as she stood without the tent of Holofernes, till they told him of her. <sup>19\u00a0</sup>And they wondered at her beauty, and admired the children of Israel because of her, and every one said to his neighbour, Who would despise this people, that have among them such women? surely it is not good that one man of them be left who being let go might deceive the whole earth. <sup>20\u00a0</sup>And they that lay near Holofernes went out, and all his servants and they brought her into the tent. <sup>21\u00a0</sup>Now Holofernes rested upon his bed under a canopy, which was woven with purple, and gold, and emeralds, and precious stones. <sup>22\u00a0</sup>So they shewed him of her; and he came out before his tent with silver lamps going before him. <sup>23\u00a0</sup>And when Judith was come before him and his servants they all marvelled at the beauty of her countenance; and she fell down upon her face, and did reverence unto him: and his servants took her up.<br/></p>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"Here ends the Reading."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"TE DEUM LAUDAMUS"},{"line_type":"subheading","content":"We Praise You, O God"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"We praise you, O God; we acclaim you as Lord; *"},{"line_type":"congregation","content":"all creation worships you, the Father everlasting."},{"line_type":"congregation","content":"To you all angels, all the powers of heaven, *"},{"line_type":"congregation","content":"the cherubim and seraphim, sing in endless praise:"},{"line_type":"congregation","content":"Holy, Holy, Holy, Lord God of power and might, *"},{"line_type":"congregation","content":"heaven and earth are full of your glory."},{"line_type":"congregation","content":"The glorious company of apostles praise you. *"},{"line_type":"congregation","content":"The noble fellowship of prophets praise you."},{"line_type":"congregation","content":"The white-robed army of martyrs praise you. *"},{"line_type":"congregation","content":"Throughout the world the holy Church acclaims you:"},{"line_type":"congregation","content":"Father, of majesty unbounded,"},{"line_type":"congregation","content":"your true and only Son, worthy of all praise, *"},{"line_type":"congregation","content":"and the Holy Spirit, advocate and guide."},{"line_type":"congregation","content":"You, Christ, are the king of glory, *"},{"line_type":"congregation","content":"the eternal Son of the Father."},{"line_type":"congregation","content":"When you took our flesh to set us free *"},{"line_type":"congregation","content":"you humbly chose the Virgin\u2019s womb."},{"line_type":"congregation","content":"You overcame the sting of death *"},{"line_type":"congregation","content":"and opened the kingdom of heaven to all believers."},{"line_type":"congregation","content":"You are seated at God\u2019s right hand in glory. *"},{"line_type":"congregation","content":"We believe that you will come to be our judge."},{"line_type":"congregation","content":"Come then, Lord, and help your people, *"},{"line_type":"congregation","content":"bought with the price of your own blood,"},{"line_type":"congregation","content":"and bring us with your saints *"},{"line_type":"congregation","content":"to glory everlasting."},{"line_type":"rubric","content":"The following verses may be omitted"},{"line_type":"congregation","content":"Save your people, Lord, and bless your inheritance;*"},{"line_type":"congregation","content":"govern and uphold them now and always."},{"line_type":"congregation","content":"Day by day we bless you; *"},{"line_type":"congregation","content":"we praise your Name for ever."},{"line_type":"congregation","content":"Keep us today, Lord, from all sin; *"},{"line_type":"congregation","content":"have mercy on us, Lord, have mercy."},{"line_type":"congregation","content":"Lord, show us your love and mercy, *"},{"line_type":"congregation","content":"for we have put our trust in you."},{"line_type":"congregation","content":"In you, Lord, is our hope; *"},{"line_type":"congregation","content":"let us never be put to shame."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Acts 16:6-40"},{"line_type":"reader","content":"A reading from the Acts of the Apostles, beginning with the sixteenth chapter, the sixth verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_802d1166-05a9-5f75-a99b-f5ff97789a32'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p><span class=\"text Acts-16-6\" id=\"en-AKJV-27490\"><sup class=\"versenum\">6\u00a0</sup>Now when they had gone throughout Phrygia and the region of Galatia, and were forbidden of the Holy Ghost to preach the word in Asia, </span> <span class=\"text Acts-16-7\" id=\"en-AKJV-27491\"><sup class=\"versenum\">7\u00a0</sup>after they were come to Mysia, they assayed to go into Bithynia: but the Spirit suffered them not. </span> <span class=\"text Acts-16-8\" id=\"en-AKJV-27492\"><sup class=\"versenum\">8\u00a0</sup>And they passing by Mysia came down to Troas. </span> <span class=\"text Acts-16-9\" id=\"en-AKJV-27493\"><sup class=\"versenum\">9\u00a0</sup>And a vision appeared to Paul in the night; There stood a man of Macedonia, and prayed him, saying, Come over into Macedonia, and help us. </span> <span class=\"text Acts-16-10\" id=\"en-AKJV-27494\"><sup class=\"versenum\">10\u00a0</sup>And after he had seen the vision, immediately we endeavoured to go into Macedonia, assuredly gathering that the Lord had called us for to preach the gospel unto them. </span> <span class=\"text Acts-16-11\" id=\"en-AKJV-27495\"><sup class=\"versenum\">11\u00a0</sup>Therefore loosing from Troas, we came with a straight course to Samothracia, and the next day to Neapolis; </span> <span class=\"text Acts-16-12\" id=\"en-AKJV-27496\"><sup class=\"versenum\">12\u00a0</sup>and from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days.</span></p><span data-line-id='secondreading_9e86401c-9ff4-5f24-ac45-e257703f6edd'></span> <p><span class=\"text Acts-16-13\" id=\"en-AKJV-27497\"><sup class=\"versenum\">13\u00a0</sup>And on the sabbath we went out of the city by a river side, where prayer was wont to be made; and we sat down, and spake unto the women which resorted thither. </span> <span class=\"text Acts-16-14\" id=\"en-AKJV-27498\"><sup class=\"versenum\">14\u00a0</sup>And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul. </span> <span class=\"text Acts-16-15\" id=\"en-AKJV-27499\"><sup class=\"versenum\">15\u00a0</sup>And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us.</span></p><span data-line-id='secondreading_2fe6eace-dc9a-5a5d-bd46-51c9f0b9de82'></span> <p><span class=\"text Acts-16-16\" id=\"en-AKJV-27500\"><sup class=\"versenum\">16\u00a0</sup>And it came to pass, as we went to prayer, a certain damsel possessed with a spirit of divination met us, which brought her masters much gain by soothsaying: </span> <span class=\"text Acts-16-17\" id=\"en-AKJV-27501\"><sup class=\"versenum\">17\u00a0</sup>the same followed Paul and us, and cried, saying, These men are the servants of the most high God, which shew unto us the way of salvation. </span> <span class=\"text Acts-16-18\" id=\"en-AKJV-27502\"><sup class=\"versenum\">18\u00a0</sup>And this did she many days. But Paul, being grieved, turned and said to the spirit, I command thee in the name of Jesus Christ to come out of her. And he came out the same hour.</span></p><span data-line-id='secondreading_7be1ca4b-a748-5e38-9c04-b223597d0eef'></span> <p><span class=\"text Acts-16-19\" id=\"en-AKJV-27503\"><sup class=\"versenum\">19\u00a0</sup>And when her masters saw that the hope of their gains was gone, they caught Paul and Silas, and drew them into the marketplace unto the rulers, </span> <span class=\"text Acts-16-20\" id=\"en-AKJV-27504\"><sup class=\"versenum\">20\u00a0</sup>and brought them to the magistrates, saying, These men, being Jews, do exceedingly trouble our city, </span> <span class=\"text Acts-16-21\" id=\"en-AKJV-27505\"><sup class=\"versenum\">21\u00a0</sup>and teach customs, which are not lawful for us to receive, neither to observe, being Romans. </span> <span class=\"text Acts-16-22\" id=\"en-AKJV-27506\"><sup class=\"versenum\">22\u00a0</sup>And the multitude rose up together against them: and the magistrates rent off their clothes, and commanded to beat them. </span> <span class=\"text Acts-16-23\" id=\"en-AKJV-27507\"><sup class=\"versenum\">23\u00a0</sup>And when they had laid many stripes upon them, they cast them into prison, charging the jailor to keep them safely: </span> <span class=\"text Acts-16-24\" id=\"en-AKJV-27508\"><sup class=\"versenum\">24\u00a0</sup>who, having received such a charge, thrust them into the inner prison, and made their feet fast in the stocks.</span></p><span data-line-id='secondreading_7b124502-8042-5729-9eb4-ee10b538d79a'></span> <p><span class=\"text Acts-16-25\" id=\"en-AKJV-27509\"><sup class=\"versenum\">25\u00a0</sup>And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them. </span> <span class=\"text Acts-16-26\" id=\"en-AKJV-27510\"><sup class=\"versenum\">26\u00a0</sup>And suddenly there was a great earthquake, so that the foundations of the prison were shaken: and immediately all the doors were opened, and every one\u2019s bands were loosed. </span> <span class=\"text Acts-16-27\" id=\"en-AKJV-27511\"><sup class=\"versenum\">27\u00a0</sup>And the keeper of the prison awaking out of his sleep, and seeing the prison doors open, he drew out his sword, and would have killed himself, supposing that the prisoners had been fled. </span> <span class=\"text Acts-16-28\" id=\"en-AKJV-27512\"><sup class=\"versenum\">28\u00a0</sup>But Paul cried with a loud voice, saying, Do thyself no harm: for we are all here. </span> <span class=\"text Acts-16-29\" id=\"en-AKJV-27513\"><sup class=\"versenum\">29\u00a0</sup>Then he called for a light, and sprang in, and came trembling, and fell down before Paul and Silas, </span> <span class=\"text Acts-16-30\" id=\"en-AKJV-27514\"><sup class=\"versenum\">30\u00a0</sup>and brought them out, and said, Sirs, what must I do to be saved? </span> <span class=\"text Acts-16-31\" id=\"en-AKJV-27515\"><sup class=\"versenum\">31\u00a0</sup>And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house. </span> <span class=\"text Acts-16-32\" id=\"en-AKJV-27516\"><sup class=\"versenum\">32\u00a0</sup>And they spake unto him the word of the Lord, and to all that were in his house. </span> <span class=\"text Acts-16-33\" id=\"en-AKJV-27517\"><sup class=\"versenum\">33\u00a0</sup>And he took them the same hour of the night, and washed their stripes; and was baptized, he and all his, straightway. </span> <span class=\"text Acts-16-34\" id=\"en-AKJV-27518\"><sup class=\"versenum\">34\u00a0</sup>And when he had brought them into his house, he set meat before them, and rejoiced, believing in God with all his house.</span></p><span data-line-id='secondreading_b950e95f-689d-5c3e-9bc8-81c1ecf46c60'></span> <p><span class=\"text Acts-16-35\" id=\"en-AKJV-27519\"><sup class=\"versenum\">35\u00a0</sup>And when it was day, the magistrates sent the serjeants, saying, Let those men go. </span> <span class=\"text Acts-16-36\" id=\"en-AKJV-27520\"><sup class=\"versenum\">36\u00a0</sup>And the keeper of the prison told this saying to Paul, The magistrates have sent to let you go: now therefore depart, and go in peace. </span> <span class=\"text Acts-16-37\" id=\"en-AKJV-27521\"><sup class=\"versenum\">37\u00a0</sup>But Paul said unto them, They have beaten us openly uncondemned, being Romans, and have cast us into prison; and now do they thrust us out privily? nay verily; but let them come themselves and fetch us out. </span> <span class=\"text Acts-16-38\" id=\"en-AKJV-27522\"><sup class=\"versenum\">38\u00a0</sup>And the serjeants told these words unto the magistrates: and they feared, when they heard that they were Romans. </span> <span class=\"text Acts-16-39\" id=\"en-AKJV-27523\"><sup class=\"versenum\">39\u00a0</sup>And they came and besought them, and brought them out, and desired them to depart out of the city. </span> <span class=\"text Acts-16-40\" id=\"en-AKJV-27524\"><sup class=\"versenum\">40\u00a0</sup>And they went out of the prison, and entered into the house of Lydia: and when they had seen the brethren, they comforted them, and departed.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"BENEDICTUS"},{"line_type":"subheading","content":"The Song of Zechariah"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Blessed be the Lord, the God of Israel; *"},{"line_type":"congregation","content":"he has come to his people and set them free."},{"line_type":"congregation","content":"He has raised up for us a mighty savior, *"},{"line_type":"congregation","content":"born of the house of his servant David."},{"line_type":"congregation","content":"Through his holy prophets he promised of old"},{"line_type":"congregation","content":"that he would save us from our enemies, *"},{"line_type":"congregation","content":"from the hands of all who hate us."},{"line_type":"congregation","content":"He promised to show mercy to our fathers *"},{"line_type":"congregation","content":"and to remember his holy covenant."},{"line_type":"congregation","content":"This was the oath he swore to our father Abraham, *"},{"line_type":"congregation","content":"to set us free from the hands of our enemies,"},{"line_type":"congregation","content":"Free to worship him without fear, *"},{"line_type":"congregation","content":"holy and righteous in his sight"},{"line_type":"congregation","content":"all the days of our life."},{"line_type":"congregation","content":"You, my child, shall be called the prophet of the Most High, *"},{"line_type":"congregation","content":"for you will go before the Lord to prepare his way,"},{"line_type":"congregation","content":"To give his people knowledge of salvation *"},{"line_type":"congregation","content":"by the forgiveness of their sins."},{"line_type":"congregation","content":"In the tender compassion of our God *"},{"line_type":"congregation","content":"the dawn from on high shall break upon us,"},{"line_type":"congregation","content":"To shine on those who dwell in darkness"},{"line_type":"congregation","content":"and in the shadow of death, *"},{"line_type":"congregation","content":"and to guide our feet into the way of peace."},{"line_type":"citation","content":"LUKE 1:68-79"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Monday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Margaret, Queen of Scotland, Reformer of the Church and Renewer of Society, 1093"},{"line_type":"leader","content":"O God, by your grace your servant Margaret, kindled by the flame of your love, became a burning and shining light in your Church, turning pride into humility and error into truth: Grant that we may be set aflame with the same spirit of love and discipline, and walk before you as children of light; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for the Renewal of Life"},{"line_type":"subheading","content":"Monday"},{"line_type":"leader","content":"O God, the King eternal, whose light divides the day from the night and turns the shadow of death into the morning: Drive far from us all wrong desires, incline our hearts to keep your law, and guide our feet into the way of peace; that, having done your will with cheerfulness during the day, we may, when night comes, rejoice to give you thanks; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"O God, you have made of one blood all the peoples of the earth, and sent your blessed Son to preach peace to those who are far off and to those who are near: Grant that people everywhere may seek after you and find you; bring the nations into your fold; pour out your Spirit upon all flesh; and hasten the coming of your kingdom; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"May the God of hope fill us with all joy and peace in believing through the power of the Holy Spirit."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"ROMANS 15:13"}]}],"midday_prayer":[{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 119:105-112"},{"line_type":"subheading","content":"Beati immaculati"},{"line_type":"leader","content":"Your word is a lantern to my feet *","preface":105},{"line_type":"leader","content":"and a light upon my path."},{"line_type":"congregation","content":"I have sworn and am steadfastly purposed *","preface":106},{"line_type":"congregation","content":"to keep your righteous judgments."},{"line_type":"leader","content":"I am troubled above measure; *","preface":107},{"line_type":"leader","content":"revive me, O L\u1d0f\u0280\u1d05, according to your word."},{"line_type":"congregation","content":"Let the freewill offerings of my mouth please you, O L\u1d0f\u0280\u1d05; *","preface":108},{"line_type":"congregation","content":"and teach me your judgments."},{"line_type":"leader","content":"My life is always in my hand, *","preface":109},{"line_type":"leader","content":"yet I do not forget your law."},{"line_type":"congregation","content":"The ungodly have laid a snare for me, *","preface":110},{"line_type":"congregation","content":"yet I have not strayed from your commandments."},{"line_type":"leader","content":"Your testimonies have I claimed as my heritage for ever, *","preface":111},{"line_type":"leader","content":"and why? They are the very joy of my heart."},{"line_type":"congregation","content":"I have applied my heart to fulfill your statutes always, *","preface":112},{"line_type":"congregation","content":"even unto the end. Samekh"},{"line_type":"heading","content":"Psalm 121"},{"line_type":"subheading","content":"Levavi oculos"},{"line_type":"leader","content":"I will lift up my eyes unto the hills; *","preface":1},{"line_type":"leader","content":"from whence comes my help?"},{"line_type":"congregation","content":"My help comes from the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"who has made heaven and earth."},{"line_type":"leader","content":"He will not let your foot be moved, *","preface":3},{"line_type":"leader","content":"and he who keeps you will not sleep."},{"line_type":"congregation","content":"Behold, he who keeps Israel *","preface":4},{"line_type":"congregation","content":"shall neither slumber nor sleep."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 himself is your keeper; *","preface":5},{"line_type":"leader","content":"the L\u1d0f\u0280\u1d05 is your defense upon your right hand,"},{"line_type":"congregation","content":"So that the sun shall not burn you by day, *","preface":6},{"line_type":"congregation","content":"neither the moon by night."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 shall preserve you from all evil; *","preface":7},{"line_type":"leader","content":"indeed, it is he who shall keep your soul."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 shall preserve your going out and your coming in, *","preface":8},{"line_type":"congregation","content":"from this time forth for evermore."},{"line_type":"heading","content":"Psalm 124"},{"line_type":"subheading","content":"Nisi quia Dominus"},{"line_type":"leader","content":"If the L\u1d0f\u0280\u1d05 himself had not been on our side, now may Israel say: *","preface":1},{"line_type":"leader","content":"if the L\u1d0f\u0280\u1d05 himself had not been on our side, when men rose up against us,"},{"line_type":"congregation","content":"Then would they have swallowed us up alive, *","preface":2},{"line_type":"congregation","content":"when they were so wrathfully displeased with us;"},{"line_type":"leader","content":"Then the waters would have drowned us, and the torrent gone over us; *","preface":3},{"line_type":"leader","content":"then the raging waters would have gone clean over us."},{"line_type":"congregation","content":"But praised be the L\u1d0f\u0280\u1d05, *","preface":4},{"line_type":"congregation","content":"who has not given us over to be prey for their teeth."},{"line_type":"leader","content":"We escaped like a bird out of the snare of the fowler; *","preface":5},{"line_type":"leader","content":"the snare is broken, and we have been delivered."},{"line_type":"congregation","content":"Our help is in the Name of the L\u1d0f\u0280\u1d05, *","preface":6},{"line_type":"congregation","content":"the maker of heaven and earth."},{"line_type":"heading","content":"Psalm 126"},{"line_type":"subheading","content":"In convertendo"},{"line_type":"leader","content":"When the L\u1d0f\u0280\u1d05 overturned the captivity of Zion, *","preface":1},{"line_type":"leader","content":"then were we like those who dream."},{"line_type":"congregation","content":"Then was our mouth filled with laughter *","preface":2},{"line_type":"congregation","content":"and our tongue with shouts of joy."},{"line_type":"leader","content":"Then they said among the nations, *","preface":3},{"line_type":"leader","content":"\u201cThe L\u1d0f\u0280\u1d05 has done great things for them.\u201d"},{"line_type":"congregation","content":"Indeed, the L\u1d0f\u0280\u1d05 has done great things for us already, *","preface":4},{"line_type":"congregation","content":"whereof we rejoice."},{"line_type":"leader","content":"Overturn our captivity, O L\u1d0f\u0280\u1d05, *","preface":5},{"line_type":"leader","content":"as when streams refresh the deserts of the south."},{"line_type":"congregation","content":"Those who sow in tears *","preface":6},{"line_type":"congregation","content":"shall reap with songs of joy."},{"line_type":"leader","content":"He who goes on his way weeping and bears good seed *","preface":7},{"line_type":"leader","content":"shall doubtless come again with joy, and bring his sheaves with him."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"Jesus said, \u201cNow is the judgment of this world; now will the ruler of this world be cast out. And I, when I am lifted up from the earth, will draw all people to myself.\u201d"},{"line_type":"citation","content":"JOHN 12:31-32"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"A meditation, silent or spoken, may follow."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"I will bless the Lord at all times."},{"line_type":"congregation_dialogue","content":"His praise shall continually be in my mouth."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Blessed Savior, at this hour you hung upon the Cross, stretching out your loving arms: Grant that all the peoples of the earth may look to you and be saved; for your tender mercies\u2019 sake."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Pour your grace into our hearts, O Lord, that we who have known the incarnation of your Son Jesus Christ, announced by an angel to the Virgin Mary, may by his Cross and passion be brought to the glory of his resurrection; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."}]}],"evening_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"Jesus spoke to them, saying, \u201cI am the light of the world. Whoever follows me will not walk in darkness, but will have the light of life.\u201d"},{"line_type":"citation","content":"JOHN 8:12"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"PHOS HILARON"},{"line_type":"subheading","content":"O Gladsome Light"},{"line_type":"congregation","content":"O gladsome light,"},{"line_type":"congregation","content":"pure brightness of the everliving Father in heaven, *"},{"line_type":"congregation","content":"O Jesus Christ, holy and blessed!"},{"line_type":"congregation","content":"Now as we come to the setting of the sun,"},{"line_type":"congregation","content":"and our eyes behold the vesper light, *"},{"line_type":"congregation","content":"we sing your praises, O God: Father, Son, and Holy Spirit."},{"line_type":"congregation","content":"You are worthy at all times to be praised by happy voices, *"},{"line_type":"congregation","content":"O Son of God, O Giver of Life,"},{"line_type":"congregation","content":"and to be glorified through all the worlds."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalm Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 44"},{"line_type":"subheading","content":"Deus, auribus"},{"line_type":"leader","content":"We have heard with our ears, O God, our fathers have told us *","preface":1},{"line_type":"leader","content":"what you did in the days of old:"},{"line_type":"congregation","content":"How you drove out the nations with your hand, and planted our fathers in the land; *","preface":2},{"line_type":"congregation","content":"how you destroyed the nations and cast them out."},{"line_type":"leader","content":"For they did not possess the land by their own sword, *","preface":3},{"line_type":"leader","content":"neither was it their own arm that helped them,"},{"line_type":"congregation","content":"But by your right hand, and your arm, and the light of your countenance, *","preface":4},{"line_type":"congregation","content":"because you favored them."},{"line_type":"leader","content":"You are my King, O God; *","preface":5},{"line_type":"leader","content":"you send help to Jacob."},{"line_type":"congregation","content":"Through you we will overthrow our enemies, *","preface":6},{"line_type":"congregation","content":"and in your Name will we tread down those who rise up against us."},{"line_type":"leader","content":"For I will not trust in my bow; *","preface":7},{"line_type":"leader","content":"it is not my sword that shall help me;"},{"line_type":"congregation","content":"But you save us from our enemies *","preface":8},{"line_type":"congregation","content":"and put to shame those who hate us."},{"line_type":"leader","content":"We make our boast in God all day long *","preface":9},{"line_type":"leader","content":"and will praise your Name for ever."},{"line_type":"congregation","content":"But now you have cast us off and put us to shame, *","preface":10},{"line_type":"congregation","content":"and you do not go forth with our armies."},{"line_type":"leader","content":"You make us turn our backs upon our enemies, *","preface":11},{"line_type":"leader","content":"so that those who hate us plunder our goods."},{"line_type":"congregation","content":"You let us be eaten up like sheep *","preface":12},{"line_type":"congregation","content":"and have scattered us among the nations."},{"line_type":"leader","content":"You sell your people for nothing *","preface":13},{"line_type":"leader","content":"and take no money for them."},{"line_type":"congregation","content":"You make us the reproach of our neighbors, *","preface":14},{"line_type":"congregation","content":"to be laughed to scorn, and held in derision by those who are round about us."},{"line_type":"leader","content":"You make us a byword among the nations, *","preface":15},{"line_type":"leader","content":"so that the peoples shake their heads at us."},{"line_type":"congregation","content":"My disgrace is daily before me, *","preface":16},{"line_type":"congregation","content":"and the shame of my face has covered me,"},{"line_type":"leader","content":"Because of the voice of the slanderer and blasphemer, *","preface":17},{"line_type":"leader","content":"because of the enemy and avenger."},{"line_type":"congregation","content":"And though all this has come upon us, yet we do not forget you, *","preface":18},{"line_type":"congregation","content":"nor have we been unfaithful to your covenant."},{"line_type":"leader","content":"Our heart has not turned back, *","preface":19},{"line_type":"leader","content":"nor have our steps departed from your way,"},{"line_type":"congregation","content":"Though you have crushed us in the haunt of jackals, *","preface":20},{"line_type":"congregation","content":"and covered us with the shadow of death."},{"line_type":"leader","content":"If we have forgotten the Name of our God, and held up our hands to any strange god, *","preface":21},{"line_type":"leader","content":"shall not God search it out? For he knows the very secrets of the heart."},{"line_type":"congregation","content":"For your sake we are killed all the day long, *","preface":22},{"line_type":"congregation","content":"and are counted as sheep appointed to be slain."},{"line_type":"leader","content":"Rise up, O Lord! Why are you sleeping? *","preface":23},{"line_type":"leader","content":"Awake, and cast us not away for ever."},{"line_type":"congregation","content":"Why do you hide your face *","preface":24},{"line_type":"congregation","content":"and forget our misery and trouble?"},{"line_type":"leader","content":"For our soul is brought low, even to the dust; *","preface":25},{"line_type":"leader","content":"our belly cleaves to the ground."},{"line_type":"congregation","content":"Arise, O Lord, and help us, *","preface":26},{"line_type":"congregation","content":"and deliver us for your mercy\u2019s sake."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Isaiah 29"},{"line_type":"reader","content":"A reading from the Prophet Isaiah, beginning with the twenty-ninth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_9818f611-24ba-5302-a097-a0d6d24f054e'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<div class=\"poetry top-1\"><p class=\"line\"><span class=\"chapter-2\"><span class=\"text Isa-29-1\" id=\"en-AKJV-18195\"><span class=\"chapternum\">29\u00a0</span>Woe to Ariel, to Ariel, the city where David dwelt!</span></span><br/><span class=\"text Isa-29-1\">add ye year to year; let them kill sacrifices.</span><br/><span class=\"text Isa-29-2\" id=\"en-AKJV-18196\"><sup class=\"versenum\">2\u00a0</sup>Yet I will distress Ariel,</span><br/><span class=\"text Isa-29-2\">and there shall be heaviness and sorrow:</span><br/><span class=\"text Isa-29-2\">and it shall be unto me as Ariel.</span><br/><span class=\"text Isa-29-3\" id=\"en-AKJV-18197\"><sup class=\"versenum\">3\u00a0</sup>And I will camp against thee round about,</span><br/><span class=\"text Isa-29-3\">and will lay siege against thee with a mount,</span><br/><span class=\"text Isa-29-3\">and I will raise forts against thee.</span><br/><span class=\"text Isa-29-4\" id=\"en-AKJV-18198\"><sup class=\"versenum\">4\u00a0</sup>And thou shalt be brought down,</span><br/><span class=\"text Isa-29-4\">and shalt speak out of the ground,</span><br/><span class=\"text Isa-29-4\">and thy speech shall be low out of the dust,</span><br/><span class=\"text Isa-29-4\">and thy voice shall be, as of one that hath a familiar spirit, out of the ground,</span><br/><span class=\"text Isa-29-4\">and thy speech shall whisper out of the dust.</span><br/><span class=\"text Isa-29-5\" id=\"en-AKJV-18199\"><sup class=\"versenum\">5\u00a0</sup>Moreover the multitude of thy strangers shall be like small dust,</span><br/><span class=\"text Isa-29-5\">and the multitude of the terrible ones shall be as chaff that passeth away:</span><br/><span class=\"text Isa-29-5\">yea, it shall be at an instant suddenly.</span><br/><span class=\"text Isa-29-6\" id=\"en-AKJV-18200\"><sup class=\"versenum\">6\u00a0</sup>Thou shalt be visited of the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> of hosts</span><br/><span class=\"text Isa-29-6\">with thunder, and with earthquake, and great noise,</span><br/><span class=\"text Isa-29-6\">with storm and tempest, and the flame of devouring fire.</span></p><span data-line-id='firstreading_4f563edb-f453-5013-9bda-099b83445bb4'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-29-7\" id=\"en-AKJV-18201\"><sup class=\"versenum\">7\u00a0</sup>And the multitude of all the nations that fight against Ariel,</span><br/><span class=\"text Isa-29-7\">even all that fight against her and her munition, and that distress her,</span><br/><span class=\"text Isa-29-7\">shall be as a dream of a night vision.</span><br/><span class=\"text Isa-29-8\" id=\"en-AKJV-18202\"><sup class=\"versenum\">8\u00a0</sup>It shall even be as when an hungry man dreameth, and, behold, he eateth;</span><br/><span class=\"text Isa-29-8\">but he awaketh, and his soul is empty:</span><br/><span class=\"text Isa-29-8\">or as when a thirsty man dreameth, and, behold, he drinketh;</span><br/><span class=\"text Isa-29-8\">but he awaketh, and, behold, he is faint, and his soul hath appetite:</span><br/><span class=\"text Isa-29-8\">so shall the multitude of all the nations be, that fight against mount Zion.</span></p><span data-line-id='firstreading_4e48674c-3b2a-57a1-b46b-c82b70ec1cc8'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-29-9\" id=\"en-AKJV-18203\"><sup class=\"versenum\">9\u00a0</sup>Stay yourselves, and wonder; cry ye out, and cry:</span><br/><span class=\"text Isa-29-9\">they are drunken, but not with wine;</span><br/><span class=\"text Isa-29-9\">they stagger, but not with strong drink.</span><br/><span class=\"text Isa-29-10\" id=\"en-AKJV-18204\"><sup class=\"versenum\">10\u00a0</sup>For the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> hath poured out upon you the spirit of deep sleep,</span><br/><span class=\"text Isa-29-10\">and hath closed your eyes:</span><br/><span class=\"text Isa-29-10\">the prophets and your rulers, the seers hath he covered.</span></p><span data-line-id='firstreading_68f4ebcd-ea50-53fa-b524-ab2986370595'></span></div> <p class=\"first-line-none top-1\"><span class=\"text Isa-29-11\" id=\"en-AKJV-18205\"><sup class=\"versenum\">11\u00a0</sup>And the vision of all is become unto you as the words of a book that is sealed, which men deliver to one that is learned, saying, Read this, I pray thee: and he saith, I cannot; for it is sealed: </span> <span class=\"text Isa-29-12\" id=\"en-AKJV-18206\"><sup class=\"versenum\">12\u00a0</sup>and the book is delivered to him that is not learned, saying, Read this, I pray thee: and he saith, I am not learned.</span></p><span data-line-id='firstreading_d713f96a-fc06-59bc-8a8f-3aa4df160a85'></span> <p><span class=\"text Isa-29-13\" id=\"en-AKJV-18207\"><sup class=\"versenum\">13\u00a0</sup>Wherefore the Lord said,</span></p><span data-line-id='firstreading_51f7a601-94f1-50f4-b903-fd64021c221e'></span><div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-29-13\">Forasmuch as this people draw near me with their mouth,</span><br/><span class=\"text Isa-29-13\">and with their lips do honour me,</span><br/><span class=\"text Isa-29-13\">but have removed their heart far from me,</span><br/><span class=\"text Isa-29-13\">and their fear toward me is taught by the precept of men:</span><br/><span class=\"text Isa-29-14\" id=\"en-AKJV-18208\"><sup class=\"versenum\">14\u00a0</sup>therefore, behold, I will proceed to do a marvellous work among this people,</span><br/><span class=\"text Isa-29-14\">even a marvellous work and a wonder:</span><br/><span class=\"text Isa-29-14\">for the wisdom of their wise men shall perish,</span><br/><span class=\"text Isa-29-14\">and the understanding of their prudent men shall be hid.</span></p><span data-line-id='firstreading_5c234632-d1a1-552d-8395-b6ba15824667'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-29-15\" id=\"en-AKJV-18209\"><sup class=\"versenum\">15\u00a0</sup>Woe unto them that seek deep to hide their counsel from the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>,</span><br/><span class=\"text Isa-29-15\">and their works are in the dark, and they say,</span><br/><span class=\"text Isa-29-15\">Who seeth us? and who knoweth us?</span><br/><span class=\"text Isa-29-16\" id=\"en-AKJV-18210\"><sup class=\"versenum\">16\u00a0</sup>Surely your turning of things upside down shall be esteemed as the potter\u2019s clay:</span><br/><span class=\"text Isa-29-16\">for shall the work say of him that made it,</span><br/><span class=\"text Isa-29-16\">He made me not?</span><br/><span class=\"text Isa-29-16\">or shall the thing framed say of him that framed it,</span><br/><span class=\"text Isa-29-16\">He had no understanding?</span></p><span data-line-id='firstreading_4a73643a-7eca-533b-bb68-6ebd2667963f'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-29-17\" id=\"en-AKJV-18211\"><sup class=\"versenum\">17\u00a0</sup>Is it not yet a very little while,</span><br/><span class=\"text Isa-29-17\">and Lebanon shall be turned into a fruitful field,</span><br/><span class=\"text Isa-29-17\">and the fruitful field shall be esteemed as a forest?</span><br/><span class=\"text Isa-29-18\" id=\"en-AKJV-18212\"><sup class=\"versenum\">18\u00a0</sup>And in that day shall the deaf hear the words of the book,</span><br/><span class=\"text Isa-29-18\">and the eyes of the blind shall see out of obscurity,</span><br/><span class=\"text Isa-29-18\">and out of darkness.</span><br/><span class=\"text Isa-29-19\" id=\"en-AKJV-18213\"><sup class=\"versenum\">19\u00a0</sup>The meek also shall increase their joy in the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>,</span><br/><span class=\"text Isa-29-19\">and the poor among men shall rejoice in the Holy One of Israel.</span><br/><span class=\"text Isa-29-20\" id=\"en-AKJV-18214\"><sup class=\"versenum\">20\u00a0</sup>For the terrible one is brought to nought,</span><br/><span class=\"text Isa-29-20\">and the scorner is consumed,</span><br/><span class=\"text Isa-29-20\">and all that watch for iniquity are cut off:</span><br/><span class=\"text Isa-29-21\" id=\"en-AKJV-18215\"><sup class=\"versenum\">21\u00a0</sup>that make a man an offender for a word,</span><br/><span class=\"text Isa-29-21\">and lay a snare for him that reproveth in the gate,</span><br/><span class=\"text Isa-29-21\">and turn aside the just for a thing of nought.</span></p><span data-line-id='firstreading_36885d05-7c02-50eb-ba7a-73662f684bcb'></span></div> <p class=\"first-line-none top-1\"><span class=\"text Isa-29-22\" id=\"en-AKJV-18216\"><sup class=\"versenum\">22\u00a0</sup>Therefore thus saith the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>, who redeemed Abraham, concerning the house of Jacob,</span></p><span data-line-id='firstreading_59743f60-47cf-56d1-b541-f8599bb2b05d'></span><div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-29-22\">Jacob shall not now be ashamed,</span><br/><span class=\"text Isa-29-22\">neither shall his face now wax pale.</span><br/><span class=\"text Isa-29-23\" id=\"en-AKJV-18217\"><sup class=\"versenum\">23\u00a0</sup>But when he seeth his children, the work of mine hands, in the midst of him,</span><br/><span class=\"text Isa-29-23\">they shall sanctify my name,</span><br/><span class=\"text Isa-29-23\">and sanctify the Holy One of Jacob,</span><br/><span class=\"text Isa-29-23\">and shall fear the God of Israel.</span><br/><span class=\"text Isa-29-24\" id=\"en-AKJV-18218\"><sup class=\"versenum\">24\u00a0</sup>They also that erred in spirit shall come to understanding,</span><br/><span class=\"text Isa-29-24\">and they that murmured shall learn doctrine.</span></p></div> </div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"MAGNIFICAT"},{"line_type":"subheading","content":"The Song of Mary"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"My soul magnifies the Lord, *"},{"line_type":"congregation","content":"and my spirit rejoices in God my Savior;"},{"line_type":"congregation","content":"For he has regarded *"},{"line_type":"congregation","content":"the lowliness of his handmaiden."},{"line_type":"congregation","content":"For behold, from now on, *"},{"line_type":"congregation","content":"all generations will call me blessed;"},{"line_type":"congregation","content":"For he that is mighty has magnified me, *"},{"line_type":"congregation","content":"and holy is his Name."},{"line_type":"congregation","content":"And his mercy is on those who fear him, *"},{"line_type":"congregation","content":"throughout all generations."},{"line_type":"congregation","content":"He has shown the strength of his arm; *"},{"line_type":"congregation","content":"he has scattered the proud in the imagination of their hearts."},{"line_type":"congregation","content":"He has brought down the mighty from their thrones, *"},{"line_type":"congregation","content":"and has exalted the humble and meek."},{"line_type":"congregation","content":"He has filled the hungry with good things, *"},{"line_type":"congregation","content":"and the rich he has sent empty away."},{"line_type":"congregation","content":"He, remembering his mercy, has helped his servant Israel, *"},{"line_type":"congregation","content":"as he promised to our fathers, Abraham and his seed for ever."},{"line_type":"citation","content":"LUKE 1:46-55"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Luke 2:22-52"},{"line_type":"reader","content":"A reading from the Gospel of our Lord Jesus Christ according to St. Luke, beginning with the second chapter, the twenty-second verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_1b37b356-2898-53a2-a021-970379dec8fa'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p><span class=\"text Luke-2-22\" id=\"en-AKJV-24996\"><sup class=\"versenum\">22\u00a0</sup>And when the days of her purification according to the law of Moses were accomplished, they brought him to Jerusalem, to present him to the Lord; </span> <span class=\"text Luke-2-23\" id=\"en-AKJV-24997\"><sup class=\"versenum\">23\u00a0</sup>(as it is written in the law of the Lord, Every male that openeth the womb shall be called holy to the Lord;) </span> <span class=\"text Luke-2-24\" id=\"en-AKJV-24998\"><sup class=\"versenum\">24\u00a0</sup>and to offer a sacrifice according to that which is said in the law of the Lord, A pair of turtledoves, or two young pigeons. </span> <span class=\"text Luke-2-25\" id=\"en-AKJV-24999\"><sup class=\"versenum\">25\u00a0</sup>And, behold, there was a man in Jerusalem, whose name was Simeon; and the same man was just and devout, waiting for the consolation of Israel: and the Holy Ghost was upon him. </span> <span class=\"text Luke-2-26\" id=\"en-AKJV-25000\"><sup class=\"versenum\">26\u00a0</sup>And it was revealed unto him by the Holy Ghost, that he should not see death, before he had seen the Lord\u2019s Christ. </span> <span class=\"text Luke-2-27\" id=\"en-AKJV-25001\"><sup class=\"versenum\">27\u00a0</sup>And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law, </span> <span class=\"text Luke-2-28\" id=\"en-AKJV-25002\"><sup class=\"versenum\">28\u00a0</sup>then took he him up in his arms, and blessed God, and said,</span></p><span data-line-id='secondreading_11235ec3-5885-5d62-a411-90314b8dacd6'></span> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Luke-2-29\" id=\"en-AKJV-25003\"><sup class=\"versenum\">29\u00a0</sup>Lord, now lettest thou thy servant depart in peace,</span><br/><span class=\"text Luke-2-29\">according to thy word:</span><br/><span class=\"text Luke-2-30\" id=\"en-AKJV-25004\"><sup class=\"versenum\">30\u00a0</sup>for mine eyes have seen thy salvation,</span><br/><span class=\"text Luke-2-31\" id=\"en-AKJV-25005\"><sup class=\"versenum\">31\u00a0</sup>which thou hast prepared before the face of all people;</span><br/><span class=\"text Luke-2-32\" id=\"en-AKJV-25006\"><sup class=\"versenum\">32\u00a0</sup>a light to lighten the Gentiles,</span><br/><span class=\"text Luke-2-32\">and the glory of thy people Israel.</span></p><span data-line-id='secondreading_af391a47-ac33-5aad-9772-d280a620b3f2'></span></div> <p class=\"first-line-none top-1\"><span class=\"text Luke-2-33\" id=\"en-AKJV-25007\"><sup class=\"versenum\">33\u00a0</sup>And Joseph and his mother marvelled at those things which were spoken of him. </span> <span class=\"text Luke-2-34\" id=\"en-AKJV-25008\"><sup class=\"versenum\">34\u00a0</sup>And Simeon blessed them, and said unto Mary his mother, Behold, this child is set for the fall and rising again of many in Israel; and for a sign which shall be spoken against; </span> <span class=\"text Luke-2-35\" id=\"en-AKJV-25009\"><sup class=\"versenum\">35\u00a0</sup>(yea, a sword shall pierce through thy own soul also,) that the thoughts of many hearts may be revealed.</span></p><span data-line-id='secondreading_6786d18b-642d-5012-9bc3-e6f1c4ff2ad4'></span> <p><span class=\"text Luke-2-36\" id=\"en-AKJV-25010\"><sup class=\"versenum\">36\u00a0</sup>And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity; </span> <span class=\"text Luke-2-37\" id=\"en-AKJV-25011\"><sup class=\"versenum\">37\u00a0</sup>and she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day. </span> <span class=\"text Luke-2-38\" id=\"en-AKJV-25012\"><sup class=\"versenum\">38\u00a0</sup>And she coming in that instant gave thanks likewise unto the Lord, and spake of him to all them that looked for redemption in Jerusalem. </span> <span class=\"text Luke-2-39\" id=\"en-AKJV-25013\"><sup class=\"versenum\">39\u00a0</sup>And when they had performed all things according to the law of the Lord, they returned into Galilee, to their own city Nazareth. </span> <span class=\"text Luke-2-40\" id=\"en-AKJV-25014\"><sup class=\"versenum\">40\u00a0</sup>And the child grew, and waxed strong in spirit, filled with wisdom: and the grace of God was upon him.</span></p><span data-line-id='secondreading_386f164d-472e-5442-8fca-b84e8e4ac0ad'></span> <p><span class=\"text Luke-2-41\" id=\"en-AKJV-25015\"><sup class=\"versenum\">41\u00a0</sup>Now his parents went to Jerusalem every year at the feast of the passover. </span> <span class=\"text Luke-2-42\" id=\"en-AKJV-25016\"><sup class=\"versenum\">42\u00a0</sup>And when he was twelve years old, they went up to Jerusalem after the custom of the feast. </span> <span class=\"text Luke-2-43\" id=\"en-AKJV-25017\"><sup class=\"versenum\">43\u00a0</sup>And when they had fulfilled the days, as they returned, the child Jesus tarried behind in Jerusalem; and Joseph and his mother knew not of it. </span> <span class=\"text Luke-2-44\" id=\"en-AKJV-25018\"><sup class=\"versenum\">44\u00a0</sup>But they, supposing him to have been in the company, went a day\u2019s journey; and they sought him among their kinsfolk and acquaintance. </span> <span class=\"text Luke-2-45\" id=\"en-AKJV-25019\"><sup class=\"versenum\">45\u00a0</sup>And when they found him not, they turned back again to Jerusalem, seeking him. </span> <span class=\"text Luke-2-46\" id=\"en-AKJV-25020\"><sup class=\"versenum\">46\u00a0</sup>And it came to pass, that after three days they found him in the temple, sitting in the midst of the doctors, both hearing them, and asking them questions. </span> <span class=\"text Luke-2-47\" id=\"en-AKJV-25021\"><sup class=\"versenum\">47\u00a0</sup>And all that heard him were astonished at his understanding and answers. </span> <span class=\"text Luke-2-48\" id=\"en-AKJV-25022\"><sup class=\"versenum\">48\u00a0</sup>And when they saw him, they were amazed: and his mother said unto him, Son, why hast thou thus dealt with us? behold, thy father and I have sought thee sorrowing. </span> <span class=\"text Luke-2-49\" id=\"en-AKJV-25023\"><sup class=\"versenum\">49\u00a0</sup>And he said unto them, How is it that ye sought me? wist ye not that I must be about my Father\u2019s business? </span> <span class=\"text Luke-2-50\" id=\"en-AKJV-25024\"><sup class=\"versenum\">50\u00a0</sup>And they understood not the saying which he spake unto them. </span> <span class=\"text Luke-2-51\" id=\"en-AKJV-25025\"><sup class=\"versenum\">51\u00a0</sup>And he went down with them, and came to Nazareth, and was subject unto them: but his mother kept all these sayings in her heart. </span> <span class=\"text Luke-2-52\" id=\"en-AKJV-25026\"><sup class=\"versenum\">52\u00a0</sup>And Jesus increased in wisdom and stature, and in favour with God and man.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"NUNC DIMITTIS"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"citation","content":"LUKE 2:29-32"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Monday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Margaret, Queen of Scotland, Reformer of the Church and Renewer of Society, 1093"},{"line_type":"leader","content":"O God, by your grace your servant Margaret, kindled by the flame of your love, became a burning and shining light in your Church, turning pride into humility and error into truth: Grant that we may be set aflame with the same spirit of love and discipline, and walk before you as children of light; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Peace"},{"line_type":"subheading","content":"Monday"},{"line_type":"leader","content":"O God, the source of all holy desires, all good counsels, and all just works: Give to your servants that peace which the world cannot give, that our hearts may be set to obey your commandments, and that we, being defended from the fear of our enemies, may pass our time in rest and quietness; through the merits of Jesus Christ our Savior."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"O God, you manifest in your servants the signs of your presence: Send forth upon us the Spirit of love, that in companionship with one another your abounding grace may increase among us; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"May the God of hope fill us with all joy and peace in believing through the power of the Holy Spirit."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"ROMANS 15:13"}]}],"compline":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"rubric","content":"The Officiant begins:"},{"line_type":"leader_dialogue","content":"The Lord Almighty grant us a peaceful night and a perfect end."},{"line_type":"congregation_dialogue","content":"Amen."},{"line_type":"leader_dialogue","content":"Our help is in the Name of the Lord;"},{"line_type":"congregation_dialogue","content":"The maker of heaven and earth."}]},{"name":"Confession","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant continues"},{"line_type":"leader_dialogue","content":"Let us humbly confess our sins unto Almighty God."},{"line_type":"rubric","content":"Silence may be kept. The Officiant and People then say"},{"line_type":"congregation","content":"Almighty God and Father, we confess to you,"},{"line_type":"congregation","content":"to one another, and to the whole company of heaven,"},{"line_type":"congregation","content":"that we have sinned, through our own fault,"},{"line_type":"congregation","content":"in thought, and word, and deed, and in what we have left undone."},{"line_type":"congregation","content":"For the sake of your Son our Lord Jesus Christ,"},{"line_type":"congregation","content":"have mercy upon us, forgive us our sins,"},{"line_type":"congregation","content":"and by the power of your Holy Spirit,"},{"line_type":"congregation","content":"raise us up to serve you in newness of life,"},{"line_type":"congregation","content":"to the glory of your Name. Amen."},{"line_type":"rubric","content":"The Officiant alone says"},{"line_type":"leader","content":"May almighty God grant us forgiveness of all our sins, and the grace and comfort of the Holy Spirit."},{"line_type":"congregation","content":"Amen."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 4"},{"line_type":"subheading","content":"Cum invocarem"},{"line_type":"leader","content":"Hear me when I call, O God of my righteousness; *","preface":1},{"line_type":"leader","content":"you set me free when I was in trouble; have mercy upon me, and hear my prayer."},{"line_type":"congregation","content":"O you children of men, how long will you blaspheme my honor, *","preface":2},{"line_type":"congregation","content":"and have such pleasure in vanity, and seek after falsehood?"},{"line_type":"leader","content":"Know this also, that the L\u1d0f\u0280\u1d05 has chosen for himself the one that is godly; *","preface":3},{"line_type":"leader","content":"when I call upon the L\u1d0f\u0280\u1d05, he will hear me."},{"line_type":"congregation","content":"Stand in awe, and sin not; *","preface":4},{"line_type":"congregation","content":"commune with your own heart upon your bed, and be still."},{"line_type":"leader","content":"Offer the sacrifice of righteousness *","preface":5},{"line_type":"leader","content":"and put your trust in the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"There are many that say, \u201cWho will show us any good?\u201d *","preface":6},{"line_type":"congregation","content":"L\u1d0f\u0280\u1d05, lift up the light of your countenance upon us."},{"line_type":"leader","content":"You have put gladness in my heart, *","preface":7},{"line_type":"leader","content":"more than when others\u2019 grain and wine and oil increased."},{"line_type":"congregation","content":"I will lay me down in peace, and take my rest; *","preface":8},{"line_type":"congregation","content":"for you, L\u1d0f\u0280\u1d05, only, make me dwell in safety."},{"line_type":"heading","content":"Psalm 31:1-6"},{"line_type":"subheading","content":"In te, Domine, speravi"},{"line_type":"leader","content":"In you, O L\u1d0f\u0280\u1d05, have I put my trust; *","preface":1},{"line_type":"leader","content":"let me never be put to confusion; deliver me in your righteousness."},{"line_type":"congregation","content":"Bow down your ear to me, *","preface":2},{"line_type":"congregation","content":"make haste to deliver me,"},{"line_type":"leader","content":"And be my strong rock and house of defense, *","preface":3},{"line_type":"leader","content":"that you may save me."},{"line_type":"congregation","content":"For you are my strong rock and my castle; *","preface":4},{"line_type":"congregation","content":"be also my guide, and lead me for your Name\u2019s sake."},{"line_type":"leader","content":"Draw me out of the net that they have laid secretly for me, *","preface":5},{"line_type":"leader","content":"for you are my strength."},{"line_type":"congregation","content":"Into your hands I commend my spirit, *","preface":6},{"line_type":"congregation","content":"for you have redeemed me, O L\u1d0f\u0280\u1d05, O God of truth."},{"line_type":"heading","content":"Psalm 91"},{"line_type":"subheading","content":"Qui habitat"},{"line_type":"leader","content":"Whoever dwells under the defense of the Most High *","preface":1},{"line_type":"leader","content":"shall abide under the shadow of the Almighty."},{"line_type":"congregation","content":"I will say unto the L\u1d0f\u0280\u1d05, \u201cYou are my refuge and my stronghold, *","preface":2},{"line_type":"congregation","content":"my God in whom I will trust.\u201d"},{"line_type":"leader","content":"For he shall deliver you from the snare of the hunter *","preface":3},{"line_type":"leader","content":"and from the deadly pestilence."},{"line_type":"congregation","content":"He shall defend you under his wings, and you shall be safe under his feathers; *","preface":4},{"line_type":"congregation","content":"his faithfulness and truth shall be your shield and buckler."},{"line_type":"leader","content":"You shall not be afraid of any terror by night, *","preface":5},{"line_type":"leader","content":"nor of the arrow that flies by day,"},{"line_type":"congregation","content":"Of the pestilence that walks in darkness, *","preface":6},{"line_type":"congregation","content":"nor of the sickness that destroys at noonday."},{"line_type":"leader","content":"A thousand shall fall beside you, and ten thousand at your right hand, *","preface":7},{"line_type":"leader","content":"but it shall not come near you."},{"line_type":"congregation","content":"Indeed, with your eyes you shall behold *","preface":8},{"line_type":"congregation","content":"and see the reward of the ungodly."},{"line_type":"leader","content":"Because you have said, \u201cThe L\u1d0f\u0280\u1d05 is my refuge,\u201d *","preface":9},{"line_type":"leader","content":"and have made the Most High your stronghold,"},{"line_type":"congregation","content":"There shall no evil happen to you, *","preface":10},{"line_type":"congregation","content":"neither shall any plague come near your dwelling."},{"line_type":"leader","content":"For he shall give his angels charge over you, *","preface":11},{"line_type":"leader","content":"to keep you in all your ways."},{"line_type":"congregation","content":"They shall bear you in their hands, *","preface":12},{"line_type":"congregation","content":"that you hurt not your foot against a stone."},{"line_type":"leader","content":"You shall tread upon the lion and adder; *","preface":13},{"line_type":"leader","content":"the young lion and the serpent you shall trample under your feet."},{"line_type":"congregation","content":"\u201cBecause he has set his love upon me, therefore I will deliver him; *","preface":14},{"line_type":"congregation","content":"I will lift him up, because he has known my Name."},{"line_type":"leader","content":"He shall call upon me, and I will hear him; *","preface":15},{"line_type":"leader","content":"indeed, I am with him in trouble; I will deliver him and bring him honor."},{"line_type":"congregation","content":"With long life I will satisfy him, *","preface":16},{"line_type":"congregation","content":"and show him my salvation.\u201d"},{"line_type":"heading","content":"Psalm 134"},{"line_type":"subheading","content":"Ecce nunc"},{"line_type":"leader","content":"Behold now, praise the L\u1d0f\u0280\u1d05, *","preface":1},{"line_type":"leader","content":"all you servants of the L\u1d0f\u0280\u1d05,"},{"line_type":"congregation","content":"You that stand by night in the house of the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"even in the courts of the house of our God."},{"line_type":"leader","content":"Lift up your hands in the sanctuary *","preface":3},{"line_type":"leader","content":"and sing praises unto the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 who made heaven and earth *","preface":4},{"line_type":"congregation","content":"give you blessing out of Zion."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"You, O Lord, are in the midst of us, and we are called by your name; do not leave us."},{"line_type":"citation","content":"JEREMIAH 14:9"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"Into your hands, O Lord, I commend my spirit;"},{"line_type":"congregation_dialogue","content":"For you have redeemed me, O Lord, O God of truth."},{"line_type":"leader_dialogue","content":"Keep me, O Lord, as the apple of your eye;"},{"line_type":"congregation_dialogue","content":"Hide me under the shadow of your wings."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"Be present, O merciful God, and protect us through the hours of this night, so that we who are wearied by the changes and chances of this life may rest in your eternal changelessness; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"Look down, O Lord, from your heavenly throne, illumine this night with your celestial brightness, and from the children of light banish the deeds of darkness; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Mission"},{"line_type":"leader","content":"Keep watch, dear Lord, with those who work, or watch, or weep this night, and give your angels charge over those who sleep. Tend the sick, Lord Christ; give rest to the weary, bless the dying, soothe the suffering, pity the afflicted, shield the joyous; and all for your love\u2019s sake."},{"line_type":"congregation","content":"Amen."}]},{"name":"Nunc Dimittis","lines":[{"line_type":"heading","content":"Nunc Dimittis"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The Officiant and People say or sing the Song of Simeon with this Antiphon, all standing"},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader_dialogue","content":"The almighty and merciful Lord, Father, Son, and Holy Spirit, bless us and keep us, this night and evermore."},{"line_type":"congregation_dialogue","content":"Amen."}]}]}};
